window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-efa02f7029fb2647"]={"versions": [{"id": "FIG-efa02f7029fb2647", "releases": ["R3.0.7", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methoden- und Prozessdiagramm (Aktivitäts- und Datenflussdarstellung nach der AUTOSAR Methodology Notation). Das Diagramm visualisiert den zentralen Systemkonfigurationsschritt („Configure System“), dessen Eingangs- und Ausgangsartefakte im ARXML-Format sowie die zugrundeliegenden Modellelemente und das ausführende Werkzeug.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Aktivität:</p>\n<ul class=\"fig-list\">\n<li><code>Configure System</code>: Zentrale Entwurfsaktivität (gelber Blockpfeil).</li>\n</ul>\n<p class=\"fig-p\">Werkzeug (Tool):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSAR System Configuration Generator</code>: Werkzeugentität zur Automatisierung bzw. Unterstützung der Systemkonfiguration.</li>\n</ul>\n<p class=\"fig-p\">Modellartefakte (.XML) und Typdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>System Configuration Input : System</code>: Aggregiertes Eingangsmodell.</li>\n<li><code>Top-Level Composition : CompositionType</code>: Software-Kompositionsstruktur der obersten Ebene.</li>\n<li><code>Mapping Constraints : SystemMapping</code>: Randbedingungen für das Mapping.</li>\n<li><code>Communication-Matrix as Constraint : CommunicationMatrixType</code>: Kommunikationsmatrix als Randbedingung.</li>\n<li><code>Topology : ...</code>: Topologiebeschreibung (Netzwerk- und Steuergeräte-Topologie).</li>\n<li><code>ECU Resource : ...</code>: Steuergeräte-Ressourcenbeschreibung.</li>\n<li><code>Collection of Available SWC Implementations</code>: Sammlung verfügbarer Software-Component-Implementierungen.</li>\n<li><code>Available SWC Implementation : Implementation</code>: Konkrete SWC-Implementierungsdaten (Kardinalität <code>*</code>).</li>\n<li><code>System Configuration Description : System</code>: Vollständige Systemkonfigurationsbeschreibung als primäres Ergebnisdokument.</li>\n<li><code>System Mapping : SystemMapping</code>: Aus der Systemkonfiguration hervorgehendes Mapping von Software auf Topologie.</li>\n<li><code>System Communication-Matrix : CommunicationMatrixType</code>: Generierte bzw. vervollständigte System-Kommunikationsmatrix.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen & Pfeile:</p>\n<ul class=\"fig-list\">\n<li>Kompositionsbeziehungen (ausgefüllte Rauten): <code>System Configuration Input</code> bindet <code>Mapping Constraints</code> ein; <code>System Configuration Description</code> bindet <code>System Mapping</code> ein.</li>\n<li>Gestrichelte Pfeile / Referenzen: Aggregation bzw. Zerlegung von Modellelementen innerhalb des <code>System Configuration Input</code> (<code>Top-Level Composition</code>, <code>Communication-Matrix as Constraint</code>, <code>Topology</code>, <code>ECU Resource</code>) sowie Zuordnung zur <code>System Configuration Description</code>.</li>\n<li>Durchgezogene Flusskanten: <code>System Configuration Input</code> und <code>Collection of Available SWC Implementations</code> fließen in <code>Configure System</code> ein; von dort führen Kanten zur <code>System Configuration Description</code> sowie zur <code>System Communication-Matrix</code>.</li>\n<li>Gestrichelte Zuordnung: <code>AUTOSAR System Configuration Generator</code> führt die Aktivität <code>Configure System</code> aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der Eingangsmodelle: Der <code>System Configuration Input</code> (bestehend aus <code>Top-Level Composition</code>, Topologie, Steuergeräte-Ressourcen sowie optionalen Mapping- und Kommunikations-Constraints) wird zusammen mit der <code>Collection of Available SWC Implementations</code> bereitgestellt.</li>\n<li>Ausführung der Konfiguration: Das Werkzeug <code>AUTOSAR System Configuration Generator</code> führt den Schritt <code>Configure System</code> aus. Dabei werden SWC-Instanzen den ECUs der Topologie zugeordnet und Netzwerksignale generiert.</li>\n<li>Generierung der Ausgangsartefakte: Als Ergebnis werden die konsolidierte <code>System Configuration Description</code> (inklusive des konkreten <code>System Mapping</code>) sowie die resultierende <code>System Communication-Matrix</code> erzeugt. Referenzen auf Topologie und SWC-Komponenten bleiben in der Konfigurationsbeschreibung erhalten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlicher Standardprozessschritt der AUTOSAR-Methodik für das System-Design auf Gesamtfahrzeugebene.</li>\n<li>Definiert die Trennung zwischen Eingangsrandbedingungen (<code>Constraints</code>) und dem finalen Mapping (<code>SystemMapping</code>) sowie der abgeleiteten Kommunikationsmatrix.</li>\n<li>Werkzeuganforderung: Der Konfigurationsgenerator muss Konformität zum AUTOSAR-Metamodell bezüglich der Klassen <code>System</code>, <code>SystemMapping</code>, <code>CommunicationMatrixType</code> und <code>CompositionType</code> gewährleisten.</li>\n<li>Für Entwickler und Integratoren dokumentiert das Schaubild die notwendigen Vorbedingungen (Vorhandensein der Topologie, Implementierungsbeschreibungen und SWC-Beschreibungen) vor dem Übergang zum ECU-spezifischen Extract (<code>ECU Extract of System Configuration</code>).</li>\n</ul>"}, {"id": "FIG-ae795332965ce327", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methoden- und Prozessdiagramm (Aktivitäts- und Datenflussdarstellung nach der AUTOSAR Methodology Notation). Das Diagramm visualisiert den zentralen Systemkonfigurationsschritt („Configure System“), dessen Eingangs- und Ausgangsartefakte im ARXML-Format sowie die zugrundeliegenden Modellelemente und das ausführende Werkzeug.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Aktivität:</p>\n<ul class=\"fig-list\">\n<li><code>Configure System</code>: Zentrale Entwurfsaktivität (gelber Blockpfeil).</li>\n</ul>\n<p class=\"fig-p\">Werkzeug (Tool):</p>\n<ul class=\"fig-list\">\n<li><code>AUTOSAR System Configuration Generator</code>: Werkzeugentität zur Automatisierung bzw. Unterstützung der Systemkonfiguration.</li>\n</ul>\n<p class=\"fig-p\">Modellartefakte (.XML) und Typdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>System Configuration Input : System</code>: Aggregiertes Eingangsmodell.</li>\n<li><code>Top-Level Composition : CompositionType</code>: Software-Kompositionsstruktur der obersten Ebene.</li>\n<li><code>Mapping Constraints : SystemMapping</code>: Randbedingungen für das Mapping.</li>\n<li><code>Communication-Matrix as Constraint : CommunicationMatrixType</code>: Kommunikationsmatrix als Randbedingung.</li>\n<li><code>Topology : ...</code>: Topologiebeschreibung (Netzwerk- und Steuergeräte-Topologie).</li>\n<li><code>ECU Resource : ...</code>: Steuergeräte-Ressourcenbeschreibung.</li>\n<li><code>Collection of Available SWC Implementations</code>: Sammlung verfügbarer Software-Component-Implementierungen.</li>\n<li><code>Available SWC Implementation : Implementation</code>: Konkrete SWC-Implementierungsdaten (Kardinalität <code>*</code>).</li>\n<li><code>System Configuration Description : System</code>: Vollständige Systemkonfigurationsbeschreibung als primäres Ergebnisdokument.</li>\n<li><code>System Mapping : SystemMapping</code>: Aus der Systemkonfiguration hervorgehendes Mapping von Software auf Topologie.</li>\n<li><code>System Communication-Matrix : CommunicationMatrixType</code>: Generierte bzw. vervollständigte System-Kommunikationsmatrix.</li>\n</ul>\n<p class=\"fig-p\">Beziehungen & Pfeile:</p>\n<ul class=\"fig-list\">\n<li>Kompositionsbeziehungen (ausgefüllte Rauten): <code>System Configuration Input</code> bindet <code>Mapping Constraints</code> ein; <code>System Configuration Description</code> bindet <code>System Mapping</code> ein.</li>\n<li>Gestrichelte Pfeile / Referenzen: Aggregation bzw. Zerlegung von Modellelementen innerhalb des <code>System Configuration Input</code> (<code>Top-Level Composition</code>, <code>Communication-Matrix as Constraint</code>, <code>Topology</code>, <code>ECU Resource</code>) sowie Zuordnung zur <code>System Configuration Description</code>.</li>\n<li>Durchgezogene Flusskanten: <code>System Configuration Input</code> und <code>Collection of Available SWC Implementations</code> fließen in <code>Configure System</code> ein; von dort führen Kanten zur <code>System Configuration Description</code> sowie zur <code>System Communication-Matrix</code>.</li>\n<li>Gestrichelte Zuordnung: <code>AUTOSAR System Configuration Generator</code> führt die Aktivität <code>Configure System</code> aus.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Bereitstellung der Eingangsmodelle: Der <code>System Configuration Input</code> (bestehend aus <code>Top-Level Composition</code>, Topologie, Steuergeräte-Ressourcen sowie optionalen Mapping- und Kommunikations-Constraints) wird zusammen mit der <code>Collection of Available SWC Implementations</code> bereitgestellt.</li>\n<li>Ausführung der Konfiguration: Das Werkzeug <code>AUTOSAR System Configuration Generator</code> führt den Schritt <code>Configure System</code> aus. Dabei werden SWC-Instanzen den ECUs der Topologie zugeordnet und Netzwerksignale generiert.</li>\n<li>Generierung der Ausgangsartefakte: Als Ergebnis werden die konsolidierte <code>System Configuration Description</code> (inklusive des konkreten <code>System Mapping</code>) sowie die resultierende <code>System Communication-Matrix</code> erzeugt. Referenzen auf Topologie und SWC-Komponenten bleiben in der Konfigurationsbeschreibung erhalten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindlicher Standardprozessschritt der AUTOSAR-Methodik für das System-Design auf Gesamtfahrzeugebene.</li>\n<li>Definiert die Trennung zwischen Eingangsrandbedingungen (<code>Constraints</code>) und dem finalen Mapping (<code>SystemMapping</code>) sowie der abgeleiteten Kommunikationsmatrix.</li>\n<li>Werkzeuganforderung: Der Konfigurationsgenerator muss Konformität zum AUTOSAR-Metamodell bezüglich der Klassen <code>System</code>, <code>SystemMapping</code>, <code>CommunicationMatrixType</code> und <code>CompositionType</code> gewährleisten.</li>\n<li>Für Entwickler und Integratoren dokumentiert das Schaubild die notwendigen Vorbedingungen (Vorhandensein der Topologie, Implementierungsbeschreibungen und SWC-Beschreibungen) vor dem Übergang zum ECU-spezifischen Extract (<code>ECU Extract of System Configuration</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-efa02f7029fb2647", "to": "FIG-ae795332965ce327", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ae795332965ce327", "to": "FIG-efa02f7029fb2647", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
